SaxonProcessor * processor = new SaxonProcessor(false);
Xslt30Processor * xslt = processor->newXslt30Transformer();

XdmAtomicValue * value =processor->makeStringValue("Hello to you");
if(xdmvaluex !=NULL){
  cerr<<"xdmvaluex ok"<<endl;
}
XsltExecutable * executable = xslt->compileFromFile("foo.xsl");
if(executable == nullptr) {
  if(proc->exceptionOccurred()) {
      cout << "Error : " << proc->getErrorMessage() <<endl;

  }
  return;
}
executable->setInitialMatchSelectionAsFile("foo.xml");
executable->setParameter("a-param", (XdmValue *) value);

const char *result = executable->applyTemplatesReturningString();
if(result != NULL) {
  cerr<<result<<endl;
} else {
  cerr<<"Result is NULL"<<endl;
}
executable->clearParameters();
executable->clearProperties();
delete executable;
delete result;
delete value;

